from abc import ABC, abstractmethod
import math

# Before: every new rule edits this function (open/closed),
# and pricing is tangled with vehicle types.
def fee_before(vehicle_type, hours, member):
    if member:
        return 0
    if vehicle_type == "motorcycle":
        return math.ceil(hours) * 1
    if vehicle_type == "car":
        return math.ceil(hours) * 3
    raise ValueError(vehicle_type)

# After: one small interface, one class per rule.
class Pricing(ABC):
    @abstractmethod
    def fee(self, hours): ...

class Hourly(Pricing):
    def __init__(self, rate):
        self.rate = rate

    def fee(self, hours):
        return math.ceil(hours) * self.rate

class MemberFree(Pricing):
    def fee(self, hours):
        return 0

class Checkout:
    def __init__(self, pricing: Pricing):   # injected
        self.pricing = pricing

    def charge(self, hours):
        return self.pricing.fee(hours)

print(fee_before("car", 2.5, False))            # 9
print(Checkout(Hourly(3)).charge(2.5))          # 9
print(Checkout(MemberFree()).charge(9))         # 0

