from enum import Enum
import math

class Size(Enum):
    SMALL = 1        # motorcycle
    COMPACT = 2      # car
    LARGE = 3        # van

class Vehicle:
    def __init__(self, plate, size):
        self.plate, self.size = plate, size

class Spot:
    def __init__(self, spot_id, size):
        self.id, self.size, self.vehicle = spot_id, size, None

    def fits(self, vehicle):
        return (self.vehicle is None
                and vehicle.size.value <= self.size.value)

class Ticket:
    def __init__(self, vehicle, spot, start):
        self.vehicle, self.spot, self.start = vehicle, spot, start

class Hourly:
    def __init__(self, rate):
        self.rate = rate

    def fee(self, hours):
        return math.ceil(hours) * self.rate

class ParkingLot:
    def __init__(self, spots, pricing):
        # smallest first, so the first fit is the smallest fit
        self.spots = sorted(spots, key=lambda s: s.size.value)
        self.pricing = pricing          # injected strategy
        self.active = {}                # plate -> Ticket

    def park(self, vehicle, now):
        spot = next((s for s in self.spots if s.fits(vehicle)), None)
        if spot is None:
            return None                 # no free spot that fits
        spot.vehicle = vehicle
        ticket = Ticket(vehicle, spot, now)
        self.active[vehicle.plate] = ticket
        return ticket

    def leave(self, plate, now):
        ticket = self.active.pop(plate)
        ticket.spot.vehicle = None
        return self.pricing.fee(now - ticket.start)

lot = ParkingLot([Spot(3, Size.LARGE), Spot(1, Size.SMALL),
                  Spot(2, Size.COMPACT)], Hourly(3))
car = lot.park(Vehicle("CAR1", Size.COMPACT), now=0)
moto = lot.park(Vehicle("MOTO1", Size.SMALL), now=0)
car2 = lot.park(Vehicle("CAR2", Size.COMPACT), now=1)
print(car.spot.id, moto.spot.id, car2.spot.id)   # 2 1 3
print(lot.park(Vehicle("VAN1", Size.LARGE), now=1))  # None
print(lot.leave("CAR1", now=2.5))                # 9
