from datetime import date, timedelta

class Book:                        # a title: one per ISBN
    def __init__(self, isbn, title):
        self.isbn, self.title = isbn, title

class BookCopy:                    # one physical item
    def __init__(self, copy_id, book):
        self.id, self.book, self.loan = copy_id, book, None

class Member:
    MAX_LOANS = 3
    def __init__(self, name):
        self.name, self.loans = name, []

class Loan:
    PERIOD = timedelta(days=14)
    def __init__(self, copy, member, today):
        self.copy, self.member = copy, member
        self.due = today + Loan.PERIOD

    def is_overdue(self, today):
        return today > self.due

class Library:
    def __init__(self):
        self.copies = {}           # isbn -> list of BookCopy

    def add_copy(self, copy):
        self.copies.setdefault(copy.book.isbn, []).append(copy)

    def checkout(self, isbn, member, today):
        if len(member.loans) >= Member.MAX_LOANS:
            raise ValueError("loan limit reached")
        for copy in self.copies.get(isbn, []):
            if copy.loan is None:
                copy.loan = Loan(copy, member, today)
                member.loans.append(copy.loan)
                return copy.loan
        return None                # none free: offer a hold

    def return_copy(self, loan):
        loan.copy.loan = None
        loan.member.loans.remove(loan)

lib = Library()
dune = Book("9780441013593", "Dune")
lib.add_copy(BookCopy("c1", dune))
ana, ben = Member("Ana"), Member("Ben")
loan = lib.checkout(dune.isbn, ana, date(2026, 10, 1))
print(loan.due, loan.is_overdue(date(2026, 10, 20)))  # 2026-10-15 True
print(lib.checkout(dune.isbn, ben, date(2026, 10, 2)))  # None

